/* Contextual questions and a shared, user-confirmed experience archive.
 * Browser-local demo only: no model, recruitment or document API is called. */
const experienceTypes=['课程作业','个人项目','实习经历','研究经历','校园活动','其他'];
const experienceLevels={practical:'实习／项目中实际使用',course:'课程／练习中使用',concept:'仅了解基础概念',none:'暂未接触',unknown:'使用情况待说明'};
const sampleExperiences=[
 {id:'sample-comments',title:'用户评论分类项目',type:'个人项目',level:'practical',skills:['Python','信息整理'],responsibility:'使用 Python 对用户评论进行分类，归纳不同问题。',methods:'分类用户评论，整理价格、功能与体验问题。',result:'导出分类结果表和问题汇总。',source:'示例简历提取',reference:'当前原型中的示例材料',confirmed:false,updated:'2026-10-19'},
 {id:'sample-research',title:'访谈与研究资料整理',type:'研究经历',level:'unknown',skills:['用户访谈','资料研究'],responsibility:'材料提及参与访谈和资料整理，个人分工尚待核对。',methods:'',result:'',source:'示例简历提取',reference:'尚未确认个人职责',confirmed:false,updated:'2026-10-19'}
];
initialProfile.experiences=structuredClone(sampleExperiences);
if(!Array.isArray(state.profile.experiences)){
 state.profile.experiences=structuredClone(sampleExperiences);
 for(const [key,skill] of [['sql','SQL'],['interview','用户访谈']])if(state.profile[key])state.profile.experiences.push({id:'legacy-'+key,title:skill+'补充记录',type:'其他',level:'unknown',skills:[skill],responsibility:key==='sql'?'旧版已确认有基础学习或查询实践，具体情境待补充。':'旧版已确认承担过访谈项目中的具体工作，个人职责待细化。',methods:'',result:'',source:'旧版用户确认记录',reference:'迁移保留，建议重新核对',confirmed:true,updated:today()});
}
let profileSection='experiences',chatQuote=null,chatDraft='',selectionCandidate=null,experienceDraft=null,experienceReturnJob=null,experienceConversation=null;
const baseUndoLast=undoLast;

function experiences(){return state.profile.experiences||[]}
function uid(prefix='experience'){return prefix+'-'+Date.now().toString(36)+'-'+Math.random().toString(36).slice(2,8)}
function relatedExperience(j,list=experiences()){
 const key=j.sql?/SQL|数据库/i:j.id===9?/访谈|调研|研究/:new RegExp(j.tags.map(t=>t.replace(/[.*+?^${}()|[\]\\]/g,'\\$&')).join('|')||'不匹配');
 return list.filter(x=>key.test([x.title,...x.skills,x.responsibility,x.methods].join(' ')));
}
function affectedJobs(record){return state.jobs.filter(j=>relatedExperience(j,[record]).length).map(j=>j.id)}
function conversationExperiences(j){const id=j?.id||null;return [...(j?relatedExperience(j):experiences()).filter(x=>x.confirmed),...state.messages.filter(m=>m.sessionExperience&&(m.jobId||null)===id).map(m=>m.sessionExperience)]}
function needsEvidence(j){return Boolean((j.sql||j.id===9)&&!relatedExperience(j).some(x=>x.confirmed))}
function syncExperienceFlags(){const a=experiences().filter(x=>x.confirmed);state.profile.sql=a.some(x=>/SQL|数据库/i.test(x.skills.join(' ')));state.profile.interview=a.some(x=>/访谈|调研/.test(x.skills.join(' ')))}
function profilePage(){
 const p=state.profile;
 const tabs=[['preferences','求职偏好'],['resume','简历材料'],['experiences','经历与能力']];
 return `${head('个人档案','记录你做过的事，为不同岗位的匹配提供依据。',`<button class="button" onclick="openVersions()">${icon('history')}档案历史</button>`)}<div class="profile-subnav" role="tablist" aria-label="个人档案模块">${tabs.map(([v,n])=>`<button role="tab" aria-selected="${profileSection===v}" class="${profileSection===v?'active':''}" onclick="setProfileSection('${v}')">${n}${v==='experiences'?`<span>${experiences().length}</span>`:''}</button>`).join('')}</div>${profileSection==='experiences'?experienceModule():profileSection==='preferences'?`<form class="panel" onsubmit="saveProfile(event)"><h3>求职偏好</h3><div class="form-grid">${profileFields(p)}</div><div class="form-actions"><button class="button primary" type="submit">保存求职偏好</button></div></form>`:`<form class="panel" onsubmit="saveProfile(event)"><h3>简历材料</h3><label class="upload-zone" style="display:block">${icon('upload')}<strong>点击选择简历文件</strong><p>PDF、Word、Markdown 或文本</p><input type="file" accept=".pdf,.docx,.md,.txt" style="display:none" onchange="handleResume(this.files[0])"></label><div class="inline" style="margin-bottom:15px"><span class="tag purple">${icon('file')}${esc(p.resumeName)}</span><button type="button" class="link-btn" onclick="useExampleResume()">使用示例简历</button></div><div class="field"><label for="resume-text">简历原始文字</label><textarea id="resume-text" name="resume" class="input" style="min-height:260px">${esc(p.resume)}</textarea><small>保留原始材料。补充事实请使用“经历与能力”。原型仅支持读取文本文件，PDF／Word 暂不解析。</small></div><div class="form-actions"><button class="button primary" type="submit">保存材料</button></div></form>`}<div class="info-note">${icon('shield')}<span>档案、经历和对话保存在当前浏览器。记录经历不等于满足所有岗位要求，岗位中单独解释适配情况。</span></div>`;
}
function setProfileSection(v){profileSection=v;render()}
function experienceModule(){const a=experiences(),count=a.filter(x=>x.confirmed).length;return `<section class="experience-intro"><div><span class="eyebrow">YOUR EXPERIENCE</span><h2>经历与能力</h2><p>把课程、项目和实习中的个人工作说清楚。这里保存事实，岗位详情负责判断是否适配。</p><div class="tags"><span class="tag purple">${a.length} 条经历</span><span class="tag green">${count} 条本人已核对</span><span class="tag">${a.length-count} 条待核对</span></div></div><div class="experience-actions"><button class="button primary" onclick="openExperienceEditor()">${icon('plus')}添加经历</button><button class="button" onclick="startExperienceConversation()">${icon('chat')}让助手引导补充</button></div></section><div class="experience-list">${a.length?a.map(experienceCard).join(''):empty('还没有补充经历','可以从一份课程作业、一个项目或一段实习开始。','添加第一条经历','openExperienceEditor()')}</div>`}
function experienceCard(x){return `<article class="experience-card"><div class="experience-card-head"><div><span class="experience-type">${esc(x.type)}</span><h3>${esc(x.title)}</h3></div><span class="tag ${x.confirmed?'green':'orange'}">${x.confirmed?'本人已核对':'待本人核对'}</span></div><div class="tags">${x.skills.map(t=>`<span class="tag purple">${esc(t)}</span>`).join('')}<span class="tag">${experienceLevels[x.level]||experienceLevels.unknown}</span></div><dl class="experience-facts"><dt>本人工作</dt><dd>${esc(x.responsibility)}</dd>${x.methods?`<dt>使用方法</dt><dd>${esc(x.methods)}</dd>`:''}${x.result?`<dt>产出或结果</dt><dd>${esc(x.result)}</dd>`:''}</dl><div class="experience-source">${icon('file')}<span>来源：${esc(x.source)}${x.reference?' · '+esc(x.reference):''}<br>更新于 ${esc(x.updated)}</span></div><div class="experience-card-footer"><small>核对记录代表本人确认描述，不代表第三方认证</small><div class="inline"><button class="link-btn" onclick="openExperienceEditor('${x.id}')">${x.confirmed?'编辑':'核对并保存'}</button><button class="link-btn danger-text" onclick="openDeleteExperience('${x.id}')">删除</button></div></div></article>`}
function blankExperience(){return {id:uid(),title:'',type:'课程作业',level:'unknown',skills:[],responsibility:'',methods:'',result:'',source:'用户自述',reference:'',confirmed:false,updated:today()}}
function resetExperienceUi(){profileSection='experiences';chatQuote=null;chatDraft='';selectionCandidate=null;experienceDraft=null;experienceReturnJob=null;experienceConversation=null;const el=document.getElementById('chat-input');if(el)el.value='';hideSelectionAsk()}
function openExperienceEditor(id=null,draft=null,messageId=null){
 if(modal==='job')experienceReturnJob={id:drawerJob,tab:drawerTab};else if(modal!=='experience')experienceReturnJob=null;
 captureChatDraft();const found=id?experiences().find(x=>x.id===id):null;
 experienceDraft={record:structuredClone(found||draft||blankExperience()),existingId:found?.id||null,messageId,step:'edit'};showExperienceEditor();
}
function showExperienceEditor(){const d=experienceDraft;if(!d)return;const x=d.record;modal='experience';showModal(`${modalHead(d.existingId?'编辑经历与能力':'补充一条经历','填写事实，再核对保存。不确定的部分可以留空。')}<div class="experience-steps"><b>1 填写事实</b><span>2 核对并选择保存范围</span></div><form id="experience-form" onsubmit="reviewExperience(event)"><div class="form-grid"><div class="field wide"><label>经历名称</label><input class="input" name="title" value="${esc(x.title)}" required maxlength="80" placeholder="例如：数据库课程作业、社团活动、研究项目"></div><div class="field"><label>经历类型</label><select class="select" name="type">${experienceTypes.map(t=>`<option ${x.type===t?'selected':''}>${t}</option>`).join('')}</select></div><div class="field"><label>实际使用情况</label><select class="select" name="level">${Object.entries(experienceLevels).map(([v,t])=>`<option value="${v}" ${x.level===v?'selected':''}>${t}</option>`).join('')}</select></div><div class="field wide"><label>涉及的技能或方法</label><input class="input" name="skills" value="${esc(x.skills.join('、'))}" maxlength="150" placeholder="例如：SQL、访谈、实验操作、财务分析"></div><div class="field wide"><label>你本人做了什么？</label><textarea class="input" name="responsibility" required maxlength="1500" placeholder="说明自己的分工；团队做过的事，不一定都是本人完成。">${esc(x.responsibility)}</textarea></div><div class="field wide"><label>具体方法或工具（可选）</label><textarea class="input" name="methods" maxlength="1000" placeholder="例如：使用哪些操作，如何完成任务。">${esc(x.methods)}</textarea></div><div class="field wide"><label>产出或结果（可选）</label><textarea class="input" name="result" maxlength="1000" placeholder="有报告、作品、练习结果或反馈可填写，不需要编造数据。">${esc(x.result)}</textarea></div><div class="field wide"><label>材料说明（可选）</label><input class="input" name="reference" value="${esc(x.reference)}" maxlength="200" placeholder="例如：课程报告、项目文档名称；没有材料也可以记录自述。"></div></div><div class="footer"><button type="button" class="button" onclick="cancelExperienceEditor()">取消</button><button class="button primary" type="submit">下一步：核对内容</button></div></form>`,true)}
function readExperienceFields(values){const old=experienceDraft?.record||blankExperience();return {...old,title:String(values.title||'').trim().slice(0,80),type:experienceTypes.includes(values.type)?values.type:'其他',level:experienceLevels[values.level]?values.level:'unknown',skills:[...new Set(String(values.skills||'').split(/[,，、;；\n]/).map(x=>x.trim()).filter(Boolean))].slice(0,12),responsibility:String(values.responsibility||'').trim().slice(0,1500),methods:String(values.methods||'').trim().slice(0,1000),result:String(values.result||'').trim().slice(0,1000),reference:String(values.reference||'').trim().slice(0,200)}}
function reviewExperience(e){e.preventDefault();const x=readExperienceFields(Object.fromEntries(new FormData(e.target)));if(!x.title||!x.responsibility){toast('请填写经历名称与本人工作。');return}experienceDraft.record=x;experienceDraft.step='review';showExperienceReview()}
function showExperienceReview(){const d=experienceDraft;if(!d)return;modal='experience';const x=d.record;showModal(`${modalHead('核对这条补充记录','确认内容准确后，再选择是否写入个人档案。')}<div class="experience-steps"><span>1 填写事实</span><b>2 核对并选择保存范围</b></div>${experienceCard({...x,confirmed:false,source:'待确认的用户自述',updated:today()}).replace(/<div class="experience-card-footer">[\s\S]*?<\/article>/,'</article>')}<div class="info-note">${icon('info')}<span>只保存你确认的描述，不自动推断“熟练”“独立完成”或“满足岗位要求”，不自动提高匹配分数。</span></div><div class="footer experience-review-actions"><button class="button" onclick="showExperienceEditor()">返回修改</button>${d.messageId?'<button class="button" onclick="commitExperience(\'session\')">仅用于本次对话</button>':''}<button class="button primary" onclick="commitExperience('profile')">确认保存到个人档案</button></div>`,true)}
function archiveProfile(previous){state.versions=[{profile:structuredClone(previous),time:nowLabel()},...(state.versions||[])].slice(0,8)}
function commitExperience(scope='profile'){
 const d=experienceDraft;if(!d||d.step!=='review')return false;const x=d.record;if(!x.title||!x.responsibility)return false;
 const message=d.messageId?state.messages.find(m=>m.id===d.messageId):null;if(d.messageId&&(!message||message.resolved)){toast('这条补充已经处理或已过期，请重新发起。');return false}
 const previous=structuredClone(state),previousUndo=lastUndo;const record={...structuredClone(x),confirmed:true,source:'用户自述 · 本人已核对',updated:today()};
 if(scope==='profile'){
  const old=experiences().find(e=>e.id===record.id);archiveProfile(state.profile);state.profile.experiences=[...experiences().filter(e=>e.id!==record.id),record];state.profile.updated=today();syncExperienceFlags();lastUndo={kind:'experience',before:old?structuredClone(old):null,afterId:record.id};
  if(message)message.resolved='已保存到个人档案';
  const count=affectedJobs(record).length;state.history.unshift({title:'已保存经历与能力',detail:record.title+' · '+(count?`已更新 ${count} 个相关岗位的证据说明`:'保留到档案，供后续岗位使用'),time:nowLabel()});
  if(d.messageId)state.messages.push({role:'assistant',text:`已保存「${record.title}」到个人档案。${count?`已重新核对 ${count} 个相关示例岗位的证据说明。`:'后续可结合新岗位核查这条经历。'}\n\n本次不自动提高匹配分数，投递状态未改变。`,jobId:message.jobId||null});
 }else{
  if(!message)return false;message.resolved='仅用于本次对话';message.sessionExperience=record;state.messages.push({role:'assistant',text:`这次对话中会参考你补充的原话：「${record.responsibility}」。\n\n未写入个人档案，不影响其他岗位或投递记录。`,jobId:message.jobId||null});
 }
 state.history=state.history.slice(0,100);if(!save()){state=previous;lastUndo=previousUndo;return false}
 experienceDraft=null;experienceConversation=null;const back=experienceReturnJob;experienceReturnJob=null;closeOverlay();if(back)openJob(back.id,back.tab);else{profileSection='experiences';render()}
 toast(scope==='profile'?'经历已保存，可在个人档案中编辑或删除。':'仅用于本次对话，个人档案未改变。',scope==='profile');return true;
}
function cancelExperienceEditor(){const back=experienceReturnJob;experienceReturnJob=null;experienceDraft=null;closeOverlay();if(back)openJob(back.id,back.tab);else render()}
function openDeleteExperience(id){const x=experiences().find(e=>e.id===id);if(!x)return;modal='experience-delete';showModal(`${modalHead('删除这条经历？',x.title)}<p class="experience-delete-note">相关岗位将不再引用这条补充。收藏、岗位原文和投递记录都会保留，删除后可以撤回。</p><div class="footer"><button class="button" onclick="closeOverlay()">取消</button><button class="button danger" onclick="deleteExperience('${id}')">确认删除</button></div>`)}
function deleteExperience(id){const old=experiences().find(x=>x.id===id);if(!old)return false;const previous=structuredClone(state),undo=lastUndo;archiveProfile(state.profile);state.profile.experiences=experiences().filter(x=>x.id!==id);state.profile.updated=today();syncExperienceFlags();if(!addHistory('已删除经历与能力',old.title)){state=previous;lastUndo=undo;return false}lastUndo={kind:'experience',before:structuredClone(old),afterId:id};closeOverlay();render();toast('经历已删除，投递记录保持不变。',true);return true}
undoLast=function(){if(lastUndo?.kind!=='experience'){baseUndoLast();return}const previous=structuredClone(state),u=lastUndo;archiveProfile(state.profile);state.profile.experiences=experiences().filter(x=>x.id!==u.afterId);if(u.before)state.profile.experiences.push(structuredClone(u.before));syncExperienceFlags();if(!addHistory('已撤回经历修改',u.before?.title||'移除本次新增记录')){state=previous;return}lastUndo=null;render();if(modal==='job')openJob(drawerJob,drawerTab);toast('已恢复修改前的经历，其他求职记录保持不变。')};

function captureChatDraft(){const el=document.getElementById('chat-input');if(el)chatDraft=el.value}
function quoteHtml(q,removable=false){const j=job(q.jobId);return `<div class="chat-quote"><div><b>${esc(j?j.company+' · '+j.title:q.title||'岗位引用')}</b>${removable?'<button type="button" aria-label="移除引用" onclick="clearChatQuote()">×</button>':''}</div><blockquote>${esc(q.text)}</blockquote>${removable?'<small>引用不会自动发送，请在下方输入问题。</small>':''}</div>`}
function assistant(embedded=false){if(modal==='job'&&!embedded)return '<aside class="assistant-placeholder" aria-hidden="true"></aside>';const context=job(chatContext);return `<aside class="assistant ${embedded?'embedded-assistant':chatOpen?'mobile-open':''}" id="assistant"><div class="assistant-head"><span class="ai-icon">${icon('spark')}</span><div><strong>你的求职助手</strong><small>基于当前档案 · 本地演示对话</small></div>${embedded?'':`<button class="icon-btn assistant-close" style="margin-left:auto" aria-label="关闭助手" onclick="toggleChat(false)">${icon('close')}</button>`}</div>${context?`<div class="assistant-context"><span>正在讨论：${esc(context.company+' · '+context.title)}</span></div>`:'<div class="assistant-context">当前范围：个人档案与求职问题</div>'}<div class="messages" id="messages"><div class="message"><div class="who">${icon('spark')}InternPilot</div><div class="bubble">${context?'可以在左侧选中岗位文字，点击“向助手提问”。我会保留原文引用，等你输入问题后再回答。':'可以核查岗位要求，或补充一段自己真实完成的经历。补充内容经过你核对后才会写入档案。'}</div></div>${!state.messages.length?`<div class="quick-questions"><button class="quick-question" onclick="askPreset('帮我解释岗位匹配依据',${context?.id||1})">查看匹配依据${icon('arrow')}</button><button class="quick-question" onclick="startExperienceConversation()">补充经历与能力${icon('arrow')}</button></div>`:''}${state.messages.map(messageHtml).join('')}</div><div class="assistant-footer">${experienceConversation?`<div class="experience-chat-state"><span>正在补充：${esc(experienceConversation.skill||'个人经历')}</span><button onclick="cancelExperienceConversation()">取消补充</button></div>`:''}${chatQuote?quoteHtml(chatQuote,true):''}<form class="chat-compose" id="chat-form"><textarea id="chat-input" placeholder="${experienceConversation?'请描述你本人做过的事…':chatQuote?'针对引用内容，输入你的问题…':'问问岗位要求，或补充你的经历…'}" aria-label="向求职助手提问" maxlength="1500">${esc(chatDraft)}</textarea><div class="compose-tools"><span>Enter 发送 · Shift + Enter 换行</span><button class="send" type="submit" aria-label="发送消息">${icon('send')}</button></div></form><div class="assistant-note">规则化演示回复 · 不会自动发送或写入档案</div></div></aside>`}
function messageHtml(m){return `<div class="message ${m.role==='user'?'user':''}"><div class="who">${m.role==='user'?'你':icon('spark')+'InternPilot'}${m.jobId&&job(m.jobId)?`<span class="message-context">${esc(job(m.jobId).company)}</span>`:''}</div><div class="bubble">${m.quote?quoteHtml(m.quote):''}${esc(m.text)}${m.resolved?`<div class="resolved-note">${icon('check')}${esc(m.resolved)}</div>`:m.action?`<div class="inline-action">${m.action==='choose-level'?`<div class="experience-level-options">${Object.entries(experienceLevels).filter(([v])=>v!=='unknown').map(([v,t])=>`<button class="button small" onclick="chooseExperienceLevel('${v}')">${t}</button>`).join('')}</div><button class="link-btn" onclick="cancelExperienceConversation()">稍后补充</button>`:m.action==='experience-review'?`<button class="button small soft" onclick="reviewChatExperience('${m.id}')">核对补充内容</button>`:m.action==='experience-start'?'<button class="button small soft" onclick="startExperienceConversation()">补充相关经历</button>':m.action==='experience-minimal'?'<button class="button small soft" onclick="finishMinimalExperience()">按当前情况继续</button>':m.action==='days'?'<button class="button small soft" onclick="confirmDays(3)">确认改为每周 3 天</button>':m.action==='greeting'?`<button class="button small soft" onclick="openJob(${m.jobId||1},'greeting')">打开文案编辑器</button>`:m.action==='search'?'<button class="button small soft" onclick="openSearchConfig()">核对搜索方案</button>':m.action==='sql'||m.action==='interview'?`<button class="button small soft" onclick="startExperienceConversation('${m.action==='sql'?'SQL':'用户访谈'}')">细化经历后再保存</button>`:`<button class="button small soft" onclick="openJob(${m.jobId||1})">查看证据卡</button>`}</div>`:''}</div></div>`}
function bindChat(){const form=document.getElementById('chat-form'),input=document.getElementById('chat-input');form?.addEventListener('submit',e=>{e.preventDefault();const q=input.value.trim();if(q)sendChat(q)});input?.addEventListener('input',()=>{chatDraft=input.value});input?.addEventListener('keydown',e=>{if(e.key==='Enter'&&!e.shiftKey&&!e.isComposing){e.preventDefault();form.requestSubmit()}})}
function refreshConversation(){const slot=document.getElementById('job-assistant-slot');if(modal==='job'&&slot){slot.innerHTML=assistant(true);bindChat();scrollChat()}else render()}
function clearChatQuote(){captureChatDraft();chatQuote=null;refreshConversation()}
function askPreset(q,id){captureChatDraft();if(modal==='job'&&id&&Number(id)!==drawerJob)openJob(Number(id));if(id)chatContext=Number(id);if(modal!=='job')closeOverlay();chatOpen=true;sendChat(q)}
function appendAssistant(text,action=null,extra={}){state.messages.push({id:uid('message'),role:'assistant',text,action,jobId:chatContext||null,...extra});state.messages=state.messages.slice(-40)}
function inferredSkill(text=''){return /SQL|数据库/i.test(text)?'SQL':/访谈|调研/.test(text)?'用户访谈':/Python/i.test(text)?'Python':/Excel|表格/i.test(text)?'Excel':null}
function startExperienceConversation(skill=null){captureChatDraft();if(modal!=='job'){closeOverlay();chatContext=null}skill=skill||inferredSkill(chatQuote?.text||'');for(const m of state.messages)if(['choose-level','experience-minimal'].includes(m.action)&&!m.resolved)m.resolved='已重新发起补充';experienceConversation={skill,level:null,jobId:chatContext||null};chatOpen=true;appendAssistant(`我们来补充${skill?'「'+skill+'」相关':'一段个人'}经历。先说明使用情境，再记录你本人做过的事。\n\n你在哪种情况下接触或使用过？`,'choose-level');save();refreshConversation();toggleChat(true)}
function chooseExperienceLevel(level){if(!experienceConversation||!experienceLevels[level]){toast('请重新发起经历补充。');return}experienceConversation.level=level;for(const m of state.messages)if(m.action==='choose-level')m.resolved='已选择使用情境';state.messages.push({role:'user',text:experienceLevels[level],jobId:experienceConversation.jobId});appendAssistant(level==='none'?'可以保留“暂未接触”的真实情况。你可以补充说明，也可以直接核对这条记录。':level==='concept'?'你了解过哪些内容？可以说明学习范围，不需要把了解概念写成实际项目经验。':'请说清楚：这是哪次课程、项目或实习？你本人负责了什么？使用了什么方法，有什么产出？\n\n可以直接描述原话，不确定的内容先留空。',level==='none'?'experience-minimal':null);save();refreshConversation()}
function cancelExperienceConversation(){experienceConversation=null;state.messages.forEach(m=>{if(['choose-level','experience-minimal'].includes(m.action)&&!m.resolved)m.resolved='已结束补充'});save();refreshConversation()}
function experienceFromChat(q){const flow=experienceConversation||{skill:inferredSkill(q),level:'unknown',jobId:chatContext||null};const skill=flow.skill||inferredSkill(q);return {...blankExperience(),title:skill?skill+'相关经历':'本次补充的个人经历',type:flow.level==='course'?'课程作业':flow.level==='practical'?'个人项目':'其他',level:flow.level||'unknown',skills:skill?[skill]:[],responsibility:q,source:'对话原话，待本人核对'}}
function finishMinimalExperience(){if(!experienceConversation||experienceConversation.level!=='none')return;sendChat(`我暂未接触${experienceConversation.skill||'这项能力'}。`)}
function reviewChatExperience(id){const m=state.messages.find(x=>x.id===id);if(!m?.experienceDraft||m.resolved){toast('这条补充已处理，请重新发起。');return}openExperienceEditor(null,m.experienceDraft,id)}
function sendChat(q){
 q=String(q).trim();if(!q)return;const quote=chatQuote?structuredClone(chatQuote):null;if(quote)chatContext=quote.jobId;const j=job(chatContext);state.messages.push({role:'user',text:q,quote,jobId:chatContext||null});chatDraft='';chatQuote=null;
 if(experienceConversation){const draft=experienceFromChat(q);appendAssistant('已保留你补充的原话，没有推断熟练度或补写结果。\n\n请核对经历名称、使用情境和个人职责，再决定保存到档案，或仅用于本次对话。','experience-review',{experienceDraft:draft});experienceConversation=null;
 }else if(/(到岗|每周).*[三3]|[三3]天/.test(q)){appendAssistant('准备将每周可到岗时间改为 3 天。确认后重新核对到岗要求，保留现有投递记录。','days');
 }else if(/我/.test(q)&&/(学过|做过|用过|完成|负责|参与|掌握|不会|未接触)/.test(q)&&!/[？?]|是否|能不能|符合吗/.test(q)){const draft=experienceFromChat(q);appendAssistant('可以把这段描述补充为一条经历。请先核对真实情境和本人工作，再选择保存范围。','experience-review',{experienceDraft:draft});
 }else if(/补充|更新.*经历/.test(q)){appendAssistant('可以补充课程、项目、研究或实习中的具体经历。先说明使用情境，再描述本人工作，保存前由你核对。','experience-start');
 }else if(quote){const skill=inferredSkill(quote.text),a=conversationExperiences(j);appendAssistant(`你引用了「${j?.title||'当前岗位'}」中的要求。\n\n${skill?'这涉及 '+skill+'，需要区分基础学习、实际使用与独立完成任务。':'先区分岗位的具体工作、必备条件与优先条件，不能仅凭一句要求判断全部适配。'}\n\n${a.length?'当前可参考的已核对自述记录：'+a.map(x=>x.title).join('、')+'。仍需结合任务复杂度逐项核查。':'当前档案缺少已核对的对应经历，暂时保留待确认，不能直接判定你不会。'}\n\n这是规则化的本地交互演示，正式版本需结合引用和问题调用模型分析。`,'experience-start');
 }else if(/SQL|数据库|访谈|调研|能力|符合|匹配/i.test(q)){const a=conversationExperiences(j);appendAssistant(`${j?'关于「'+j.title+'」：\n\n':''}${a.length?'相关个人记录：'+a.map(x=>x.title).join('、')+'。这些是用户自述的事实，需要进一步对照岗位要求。':'现有材料没有把相关个人工作说清楚，先保留待确认。'}\n\n补充一段真实经历后，可以更新证据说明；不会自动把“学过”判断为“熟练”。`,'experience-start');
 }else if(/招呼|开场|文案/.test(q)){appendAssistant('可以根据当前岗位和示例简历准备开场白，由你核实、编辑后复制，投递状态不会自动改变。','greeting');
 }else if(/搜索|找岗位|找实习/.test(q)){appendAssistant(`当前求职条件：${state.profile.city}，${state.profile.direction}，每周最多 ${state.profile.days} 天。请先核对搜索方案。`,'search');
 }else{appendAssistant(j?`关于「${j.title}」：\n\n${j.fit}。${conflicts(j).length?'需要核对：'+conflicts(j).join('、')+'。':'已知到岗条件符合当前设置。'}\n\n可以选中左侧原文中的具体句子继续提问，或补充自己的经历。`:'可以打开岗位后选中文字提问，也可以补充一段课程、项目或实习经历。','experience-start')}
 save();refreshConversation();
}
function confirmEvidence(type){startExperienceConversation(type==='sql'?'SQL':'用户访谈')}

function openJob(id,tab='match'){
 const j=job(id);if(!j)return;captureChatDraft();if(chatQuote&&chatQuote.jobId!==j.id){chatQuote=null;toast('已切换岗位，未发送的旧岗位引用已清除。')}if(experienceConversation&&experienceConversation.jobId!==j.id){experienceConversation=null;state.messages.forEach(m=>{if(['choose-level','experience-minimal'].includes(m.action)&&!m.resolved)m.resolved='已切换岗位，请重新发起补充'})}hideSelectionAsk();drawerJob=j.id;drawerTab=tab;chatContext=j.id;modal='job';render();
 document.getElementById('overlay-root').innerHTML=`<div class="job-workspace-backdrop" onclick="if(event.target===this)closeOverlay()"><section class="job-workspace" role="dialog" aria-modal="true" aria-label="岗位详情与求职助手"><div class="job-detail-panel"><div class="drawer-header"><div class="company-row"><div class="company-logo" style="background:${j.bg};color:${j.color}">${j.initial}</div><div><div class="company-name">${esc(j.company)}</div><div class="company-meta">${esc(j.industry)} · 示例企业</div></div>${savedButton(j)}<button class="icon-btn" aria-label="关闭岗位详情" onclick="closeOverlay()">${icon('close')}</button></div><div class="job-title-row"><h2>${esc(j.title)}</h2><span class="salary">${esc(j.pay)}</span></div><div class="job-meta"><span>${icon('pin')}${j.city}</span><span>${icon('clock')}${j.days} 天/周 · ${j.months} 个月</span>${statusTag(j.status)}</div></div><div class="drawer-tabs"><div class="tabs">${[['match','匹配分析'],['jd','岗位原文'],['greeting','沟通文案'],['record','申请记录']].map(([v,n])=>`<button class="tab ${v===tab?'active':''}" onclick="openJob(${id},'${v}')">${n}</button>`).join('')}</div></div><div class="job-selection-hint">${icon('chat')}选中下方岗位文字，即可向助手提问。</div><div class="drawer-body" data-job-selection="${id}" id="job-reading-pane">${tab==='match'?matchDetail(j):tab==='jd'?jdDetail(j):tab==='greeting'?greetingDetail(j):recordDetail(j)}</div><div class="drawer-footer"><button class="button" onclick="focusJobAssistant()">${icon('chat')}向助手提问</button><div class="inline"><button class="button" onclick="openStatusModal([${id}])">更新状态</button><button class="button primary" onclick="${tab==='greeting'?`copyGreeting(${id})`:`openJob(${id},'greeting')`}">${icon(tab==='greeting'?'copy':'spark')}${tab==='greeting'?'复制招呼语':'生成招呼语'}</button></div></div></div><div id="job-assistant-slot">${assistant(true)}</div></section></div>`;document.body.style.overflow='hidden';bindChat();scrollChat();document.getElementById('job-reading-pane')?.addEventListener('scroll',hideSelectionAsk);
}
function focusJobAssistant(){document.getElementById('chat-input')?.focus()}
function closeOverlay(){captureChatDraft();hideSelectionAsk();const back=modal==='experience'?experienceReturnJob:null;if(back){experienceReturnJob=null;experienceDraft=null}document.getElementById('overlay-root').innerHTML='';document.body.style.overflow='';drawerJob=null;modal=null;render();if(back)openJob(back.id,back.tab)}
function hideSelectionAsk(){const el=document.getElementById('selection-ask');if(el)el.hidden=true;selectionCandidate=null}
function selectionDetails(selection){if(modal!=='job'||!selection||selection.isCollapsed||!selection.rangeCount)return null;const text=selection.toString().trim();if(!text||text.length>1500)return null;const range=selection.getRangeAt(0);const element=n=>n?.nodeType===1?n:n?.parentElement;const start=element(range.startContainer),end=element(range.endContainer);const a=start?.closest?.('[data-job-selection]'),b=end?.closest?.('[data-job-selection]');if(!a||a!==b||Number(a.dataset.jobSelection)!==drawerJob||start.closest('textarea,input,button,select')||end.closest('textarea,input,button,select'))return null;return {text,jobId:drawerJob,tab:drawerTab,title:job(drawerJob)?.title,rect:range.getBoundingClientRect()}}
function showSelectionAsk(selection=window.getSelection?.()){const details=selectionDetails(selection);if(!details){hideSelectionAsk();return}let el=document.getElementById('selection-ask');if(!el){el=document.createElement('button');el.id='selection-ask';el.className='selection-ask';el.type='button';el.innerHTML=icon('chat')+'向助手提问';el.addEventListener('pointerdown',e=>e.preventDefault());el.addEventListener('click',askSelectedText);document.body.appendChild(el)}selectionCandidate=details;el.hidden=false;const r=details.rect;el.style.left=Math.max(12,Math.min(r.left+r.width/2-70,window.innerWidth-156))+'px';el.style.top=Math.max(10,r.top<60?r.bottom+8:r.top-43)+'px'}
function askSelectedText(){if(!selectionCandidate)return;const q=selectionCandidate;if(q.jobId!==drawerJob||modal!=='job'){hideSelectionAsk();return}captureChatDraft();chatQuote={text:q.text,jobId:q.jobId,title:q.title,tab:q.tab};chatContext=q.jobId;hideSelectionAsk();window.getSelection?.()?.removeAllRanges();refreshConversation();focusJobAssistant()}
document.addEventListener('mouseup',e=>{if(e.target?.closest?.('#selection-ask'))return;showSelectionAsk()});
document.addEventListener('keyup',e=>{if(e.key==='Shift')showSelectionAsk()});
document.addEventListener('selectionchange',()=>{const s=window.getSelection?.();if(!s||s.isCollapsed)hideSelectionAsk()});
document.addEventListener('pointerdown',e=>{if(!e.target?.closest?.('#selection-ask,[data-job-selection]'))hideSelectionAsk()});
window.addEventListener?.('resize',hideSelectionAsk);

function baseMatchDetail(j){const c=conflicts(j),all=relatedExperience(j),confirmed=all.filter(x=>x.confirmed),missing=!confirmed.length;return `<div class="match-overview"><div class="score-circle">${effectiveScore(j)}</div><div><strong>${scoreLabel(j)}</strong><p>${esc(j.fit)}</p><span class="tag purple">示例分数，不随补充自动提高</span></div></div><div class="section-head"><h2>岗位要求与个人证据</h2><span class="tag">先核对事实，再判断适配</span></div>${evidenceCard('到岗与实习安排',`${j.city}，每周 ${j.days} 天，至少 ${j.months} 个月。`,`${state.profile.city}，每周可到岗 ${state.profile.days} 天，可持续 ${state.profile.months} 个月。`,c.length?'存在冲突':'已知条件满足',c.length?'red':'green',c.length?'技能相关不能抵消到岗条件冲突。':'未明确的信息仍需向招聘方确认。')}${evidenceCard(j.sql?'SQL 相关要求':'个人职责与相关经历',j.sql?'掌握 SQL 基础查询，能够支持日常分析。':'能够说明本人承担的工作，并提供相关经历。',missing?'当前没有本人核对过的相关补充。':confirmed.map(x=>`${x.title}（${experienceLevels[x.level]}）：${x.responsibility}${x.result?'；产出：'+x.result:''}`).join('\n'),missing?'信息待确认':'已补充自述，适配待核对','orange',missing?'简历未体现不等于不会，可以选中要求向助手提问。':'本人核对过描述，不等于第三方验证，也不直接证明满足完整岗位要求。',`startExperienceConversation('${j.sql?'SQL':'用户访谈'}')`)}${all.filter(x=>!x.confirmed).length?'<div class="info-note">'+icon('info')+'<span>档案中有待本人核对的相关记录，尚未当作已确认事实使用。</span></div>':''}<div class="evidence-card"><div class="evidence-head"><strong>补充与修正个人经历</strong><button class="link-btn" onclick="openExperienceModule()">管理经历与能力 ${icon('arrow')}</button></div><p class="evidence-note">在对话中补充和在个人档案中添加，会进入同一份记录。写入前由你确认，支持编辑、删除和撤回。</p></div>`}
function openExperienceModule(){closeOverlay();profileSection='experiences';nav('profile')}
syncExperienceFlags();
